async function findUser(env, phone) {
  const row = await env.DB.prepare("SELECT * FROM users WHERE phone = ?").bind(phone).first();
  if (!row) {
    return null;
  }
  return rowToUser(row);
}

async function saveUser(env, user) {
  await env.DB.prepare(`
    INSERT INTO users (phone, hash, salt, role, identity, large_font, nickname, city, created_at, last_login_at, common_crops)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(phone) DO UPDATE SET
      hash = excluded.hash,
      salt = excluded.salt,
      role = excluded.role,
      identity = excluded.identity,
      large_font = excluded.large_font,
      nickname = excluded.nickname,
      city = excluded.city,
      created_at = excluded.created_at,
      last_login_at = excluded.last_login_at,
      common_crops = excluded.common_crops
  `).bind(
    user.phone,
    user.hash,
    user.salt,
    user.role,
    user.identity || "",
    user.largeFont ? 1 : 0,
    user.nickname || "",
    user.city || "",
    user.createdAt,
    user.lastLoginAt,
    JSON.stringify(user.commonCrops || [])
  ).run();
}

function rowToUser(row) {
  return {
    phone: row.phone,
    hash: row.hash,
    salt: row.salt,
    role: row.role,
    identity: row.identity || "",
    largeFont: bool(row.large_font),
    nickname: row.nickname || "",
    city: row.city || "",
    createdAt: row.created_at,
    lastLoginAt: row.last_login_at,
    commonCrops: parseStringArray(row.common_crops)
  };
}

async function findSession(env, token) {
  if (!token) {
    return null;
  }
  const row = await env.DB.prepare("SELECT * FROM sessions WHERE token = ?").bind(token).first();
  if (!row) {
    return null;
  }
  if (new Date(row.expires_at).getTime() <= Date.now()) {
    await env.DB.prepare("DELETE FROM sessions WHERE token = ?").bind(token).run();
    return null;
  }
  return row;
}

async function createSession(env, phone) {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  const token = bytesToBase64(bytes).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
  const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();
  await env.DB.prepare("INSERT INTO sessions (token, phone, expires_at) VALUES (?, ?, ?)")
    .bind(token, phone, expiresAt)
    .run();
  return { token, phone, expiresAt };
}

async function deleteSession(env, token) {
  if (!token) {
    return;
  }
  await env.DB.prepare("DELETE FROM sessions WHERE token = ?").bind(token).run();
}

async function updateProfile(env, phone, nickname, city, largeFont, commonCrops) {
  const user = await findUser(env, phone);
  if (!user) {
    return;
  }
  if (user.role !== "admin" && nickname) {
    user.nickname = nickname.trim();
  }
  if (city) {
    user.city = city.trim();
  }
  if (largeFont !== null && user.identity === "individual") {
    user.largeFont = largeFont;
  }
  if (commonCrops !== undefined) {
    user.commonCrops = Array.from(new Set((commonCrops || []).map(String).filter(Boolean))).slice(0, 50);
  }
  await saveUser(env, user);
}

async function authenticateUser(env, phone, password, identity) {
  let user = await findUser(env, phone);
  if (!user) {
    if (!/^[0-9]{6}$/.test(password)) {
      return null;
    }
    const salt = bytesToBase64(crypto.getRandomValues(new Uint8Array(16)));
    user = {
      phone,
      salt,
      hash: await hashPassword(password, salt),
      role: "guest",
      identity,
      largeFont: identity === "individual",
      nickname: `用户${phone.slice(7)}`,
      city: "",
      commonCrops: [],
      createdAt: nowIso(),
      lastLoginAt: nowIso()
    };
    await saveUser(env, user);
    return user;
  }

  const expected = await hashPassword(password, user.salt);
  if (expected !== user.hash) {
    return null;
  }
  if (user.role !== "admin" && !user.identity) {
    user.identity = identity;
    user.largeFont = identity === "individual";
  } else if (user.role !== "admin" && !user.identity && !user.largeFont && identity === "individual") {
    user.largeFont = true;
  }
  user.lastLoginAt = nowIso();
  await saveUser(env, user);
  return user;
}

async function hashPassword(password, saltBase64) {
  const encoder = new TextEncoder();
  const passwordKey = await crypto.subtle.importKey(
    "raw",
    encoder.encode(password),
    "PBKDF2",
    false,
    ["deriveBits"]
  );
  const bits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      hash: "SHA-1",
      salt: base64ToBytes(saltBase64),
      iterations: 10000
    },
    passwordKey,
    256
  );
  return bytesToBase64(new Uint8Array(bits));
}

